/**
 * Handwritten transport for clients generated by `@modura/generator-sdk-ts`, which
 * import their types from this package. This is the only place in a frontend that is
 * allowed to call `fetch` for Modura operations.
 */

export interface Money {
  /** Amount in the currency's minor unit, for example cents. */
  readonly amountMinor: number;
  /** ISO 4217 code. */
  readonly currency: string;
}

/** Any JSON value, for fields the contract declares with `t.json()`. */
export type JsonValue =
  | null
  | boolean
  | number
  | string
  | readonly JsonValue[]
  | { readonly [key: string]: JsonValue };

/** Mirrors `ModuraError` in @modura/runtime-contracts, narrowed to an operation's codes. */
export interface ModuraError<Code extends string = string> {
  readonly code: Code;
  readonly message: string;
  readonly retryable: boolean;
  readonly operation?: string;
  readonly requestId?: string;
  readonly details?: Readonly<Record<string, unknown>>;
}

/**
 * Operations return a result instead of throwing, so the compiler makes callers deal
 * with the error codes the contract says are possible.
 */
export type Result<Value, Code extends string> =
  | { readonly ok: true; readonly value: Value; readonly replayed: boolean }
  | { readonly ok: false; readonly error: ModuraError<Code> };

export interface CallOptions {
  readonly signal?: AbortSignal;
}

export interface IdempotentCallOptions extends CallOptions {
  /** Unique per attempt. Reuse it when retrying the same attempt. */
  readonly idempotencyKey: string;
}

/** What the generated client passes along with each call. */
export interface TransportCallOptions extends CallOptions {
  readonly idempotencyKey?: string;
  /** The service that implements the operation, from modura.config.ts. */
  readonly service?: string;
}

export interface Transport {
  call<Value, Code extends string>(
    operation: string,
    input: unknown,
    options?: TransportCallOptions,
  ): Promise<Result<Value, Code>>;
}

export interface HttpTransportOptions {
  /** Base URL for every service not listed in `serviceUrls`. */
  readonly baseUrl: string;
  /**
   * Base URL per service, for example `{ "reports-py": "https://reports.example" }`.
   * The client routes itself, so no service has to forward another's calls.
   */
  readonly serviceUrls?: Readonly<Record<string, string>>;
  /** Bearer token, or a function that returns the current one. */
  readonly token?: string | (() => string | undefined);
  readonly fetch?: typeof globalThis.fetch;
}

export function createHttpTransport(options: HttpTransportOptions): Transport {
  const trim = (url: string) => url.replace(/\/+$/, '');
  const doFetch = options.fetch ?? globalThis.fetch.bind(globalThis);

  return {
    async call<Value, Code extends string>(
      operation: string,
      input: unknown,
      callOptions: TransportCallOptions = {},
    ): Promise<Result<Value, Code>> {
      const serviceUrl = callOptions.service ? options.serviceUrls?.[callOptions.service] : undefined;
      const baseUrl = trim(serviceUrl ?? options.baseUrl);
      const headers: Record<string, string> = {
        'content-type': 'application/json',
        accept: 'application/json',
      };
      const token = typeof options.token === 'function' ? options.token() : options.token;
      if (token) headers.authorization = `Bearer ${token}`;
      if (callOptions.idempotencyKey) headers['idempotency-key'] = callOptions.idempotencyKey;

      // INTERNAL and UNAVAILABLE are in every operation's code union (the compiler
      // implies them), so the casts below never widen what callers must handle.
      let response: Response;
      try {
        response = await doFetch(`${baseUrl}/v1/${operation}`, {
          method: 'POST',
          headers,
          body: JSON.stringify(input),
          signal: callOptions.signal,
        });
      } catch (cause) {
        if (callOptions.signal?.aborted) throw cause;
        return failure<Code>('UNAVAILABLE', `Network error: ${String(cause)}`, true, operation);
      }

      let body: unknown;
      try {
        body = await response.json();
      } catch (cause) {
        if (callOptions.signal?.aborted) throw cause;
        body = undefined;
      }
      if (response.ok) {
        // Every operation has an output type, so a success without a JSON body is a
        // broken server or proxy, not an empty result.
        if (body === undefined) {
          return failure<Code>('INTERNAL', `${response.status} response without a JSON body`, false, operation);
        }
        return {
          ok: true,
          value: body as Value,
          replayed: response.headers.get('idempotent-replayed') === 'true',
        };
      }
      if (isModuraError(body)) return { ok: false, error: body as ModuraError<Code> };
      // Gateways and load balancers answer 429, 502, 503 and 504 themselves when the
      // service is overloaded or down, so the caller may retry.
      if (UNAVAILABLE_STATUSES.has(response.status)) {
        return failure<Code>('UNAVAILABLE', `Service unavailable (${response.status})`, true, operation);
      }
      return failure<Code>(
        'INTERNAL',
        `Unexpected ${response.status} response without a Modura error body`,
        false,
        operation,
      );
    },
  };
}

const UNAVAILABLE_STATUSES = new Set([429, 502, 503, 504]);

function failure<Code extends string>(
  code: string,
  message: string,
  retryable: boolean,
  operation: string,
): Result<never, Code> {
  return { ok: false, error: { code: code as Code, message, retryable, operation } };
}

function isModuraError(value: unknown): value is ModuraError {
  if (typeof value !== 'object' || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.code === 'string' &&
    typeof candidate.message === 'string' &&
    typeof candidate.retryable === 'boolean'
  );
}
